const D = { density: .55, scale: 1, energy: .6, hue: 45, speed: 1, warp: .18, x: .5, y: .56, seed: 0, style: 'label', act: 'spin' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const TAU = 6.28318530718;
const cl = (v,a,b) => v<a?a:v>b?b:v;
const sty = P.style;
const cx = cl(P.x,.05,.95) * width;
const cy = cl(P.y,.05,.95) * height;
const um = Math.min(width,height);
const R = um * .66 * cl(P.scale,.4,2.4);
const lr = R * (.28 + .06*cl(P.warp,0,1));   // label radius (warp doubles as label-size morph)
const H = P.hue;

S.bass = (S.bass||0)*.82 + (A.bass||0)*.18;
S.tre  = (S.tre ||0)*.82 + (A.treble||0)*.18;
const glow = (.4 + .6*P.energy) * (.55 + .55*K.intensity);
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + S.bass*.7);

// ---- rotation: real-time base spin (never re-phases) + act flavour ----
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = K.t - S.pt; S.pt = K.t; dt = cl(dt,0,.1);
let rate = P.speed * (.55 + .7*K.intensity);
if (P.act === 'pulse') rate *= 1 + .8*kick;
if (P.act === 'tide')  rate *= .4 + .9*(.5 + .5*Math.sin(K.t*.05 + K.section*.8));
let scratch = 0;
if (P.act === 'scratch') scratch = Math.sin(K.t*7.5) * (S.bass*S.bass) * 2.4;
S.ang = (S.ang||0) + dt*(rate*0.95) + scratch*dt*5;
const ang = S.ang;

// ---- cached record body (disc, grooves, sheen, label plate) ----
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+P.seed+'|'+Math.round(R)+'|'+Math.round(P.density*10)+'|'+Math.round(cx)+'|'+Math.round(cy);
if (!S.base || S.key !== key) {
  const g = S.base && S.base.width===width && S.base.height===height ? S.base : createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.push(); g.translate(cx,cy);
  // vinyl body: concentric radial sheen bands
  const bands = 54;
  for (let i=bands;i>=0;i--){ const t=i/bands, rr=R*t;
    let h,s,b;
    if (sty==='blueprint'){ h=(H+195)%360; s=70; b=8 + 5*t; }
    else if (sty==='wireframe'){ h=H; s=40; b=4 + 3*t; }
    else if (sty==='chrome'){ h=(H + 300*t)%360; s=42; b=16 + 30*Math.pow(t,.7); }
    else { h=H; s=8; b=5 + 7*Math.pow(t,1.4); }   // label: warm near-black wax
    g.noStroke(); g.fill(h,s,b,100); g.ellipse(0,0,rr*2,rr*2);
  }
  // groove rings
  const NG = Math.round(28 + P.density*96);
  g.noFill();
  for (let i=0;i<NG;i++){ const t=.30 + .69*(i/NG), rr=R*t;
    let h,s,b,a,sw;
    if (sty==='wireframe'){ h=H; s=85; b=100; a=18+22*fr(i); sw=.7; }
    else if (sty==='blueprint'){ h=(H+195)%360; s=30; b=100; a=16+14*fr(i); sw=.6; }
    else if (sty==='chrome'){ h=(H+300*t)%360; s=30; b=100; a=14+16*fr(i); sw=.6; }
    else { h=H; s=6; b=10+9*fr(i); a=34+16*fr(i); sw=.6; }
    g.stroke(h,s,b,a); g.strokeWeight(sw); g.ellipse(0,0,rr*2,rr*2);
  }
  // run-out & outer rim
  g.noFill(); g.stroke(sty==='label'?H:(H+195)%360, sty==='label'?10:40, sty==='wireframe'?100:60, 60);
  g.strokeWeight(1.4); g.ellipse(0,0,R*2,R*2);
  // label plate
  if (sty==='wireframe' || sty==='blueprint'){
    g.noFill(); g.stroke((H+40)%360, sty==='blueprint'?30:90, 100, 80); g.strokeWeight(1.4);
    g.ellipse(0,0,lr*2,lr*2);
    for (let s0=0;s0<8;s0++){ const a0=s0/8*TAU; g.line(Math.cos(a0)*lr*.2,Math.sin(a0)*lr*.2, Math.cos(a0)*lr,Math.sin(a0)*lr); }
  } else {
    g.noStroke(); g.fill(H, sty==='chrome'?55:72, 86, 100); g.ellipse(0,0,lr*2,lr*2);
    g.noFill(); g.stroke(0,0,100,55); g.strokeWeight(2); g.ellipse(0,0,lr*2*.86,lr*2*.86);
    g.stroke(0,0,0,40); g.strokeWeight(1); g.ellipse(0,0,lr*2*1.02,lr*2*1.02);
  }
  g.pop(); S.base = g; S.key = key;
}
image(S.base, 0, 0);

// ---- rotating surface detail (scuffs, label sectors, marker) ----
push(); translate(cx,cy); rotate(ang);
// radial dust scuffs sweeping with the disc
const NS = Math.round(9 + P.density*26);
blendMode(ADD); noStroke();
for (let i=0;i<NS;i++){ const a0=fr(i*3)*TAU, r0=(.34+.6*fr(i*3+1))*R, len=(.05+.16*fr(i*3+2))*R;
  const x0=Math.cos(a0)*r0, y0=Math.sin(a0)*r0, x1=Math.cos(a0)*(r0+len), y1=Math.sin(a0)*(r0+len);
  stroke(H, sty==='wireframe'?60:10, 100, 8*glow); strokeWeight(.8);
  line(x0,y0,x1,y1);
}
noStroke(); blendMode(BLEND);
// label sectors + marker so rotation is unmistakable
if (sty==='label' || sty==='chrome'){
  const segs = 3;
  for (let s0=0;s0<segs;s0++){ const a0=s0/segs*TAU;
    fill((H+ s0*22)%360, 68, 96, 90);
    arc(0,0, lr*1.4, lr*1.4, a0, a0+.34);
  }
  // top marker pip
  fill(0,0,100,95); ellipse(lr*.62,0, lr*.16, lr*.16);
} else {
  stroke((H+40)%360, sty==='blueprint'?24:80, 100, 70); strokeWeight(1.2); noFill();
  arc(0,0, lr*1.3, lr*1.3, .2, 1.9);
  noStroke(); fill((H+40)%360, sty==='blueprint'?24:80, 100, 80); ellipse(lr*.55,0, lr*.14,lr*.14);
}
// spindle hole
noStroke(); fill(0,0, sty==='wireframe'?0:6, sty==='wireframe'?0:100); ellipse(0,0, um*.012, um*.012);
stroke(0,0,100,60); strokeWeight(1); noFill(); ellipse(0,0, um*.02, um*.02);
pop();

// ---- sweeping specular glint (real-time, independent) ----
const gA = K.t*0.55 + K.section*.4;
push(); translate(cx,cy); rotate(gA); blendMode(ADD); noStroke();
for (let i=0;i<6;i++){ fill(H, sty==='chrome'?20:8, 100, (5+3*i*0.0+7)*glow*.55*(1-i*0.12));
  ellipse(R*.42, 0, R*(1.3-i*.16), R*.46); }
pop();

// ---- groove shimmer ring (beat, partial-frame) ----
push(); translate(cx,cy); blendMode(ADD); noFill();
const shR = R*(.32 + .64*((K.t*.16)%1));
stroke(H, sty==='wireframe'?70:14, 100, 20*glow*(.4+.6*kick)); strokeWeight(2+3*kick);
ellipse(0,0, shR*2, shR*2);
const shR2 = R*(.32 + .64*((K.t*.16+.5)%1));
stroke(H, sty==='wireframe'?70:14, 100, 14*glow); strokeWeight(1.6);
ellipse(0,0, shR2*2, shR2*2);
pop();

// ---- tonearm shadow (static-ish, sways subtly) ----
push(); blendMode(BLEND);
const sway = Math.sin(K.t*.18)*.05 + kick*.03;
const baseX = cx + R*1.02, baseY = cy - R*1.02;
const tipX = cx + Math.cos(TAU*(.62+sway))*R*.86, tipY = cy + Math.sin(TAU*(.62+sway))*R*.86;
stroke(0,0,0,26); strokeWeight(um*.02); line(baseX,baseY, tipX,tipY);
stroke(0,0,0,34); strokeWeight(um*.011); line(baseX,baseY, tipX,tipY);
noStroke(); fill(0,0,8,70); ellipse(tipX,tipY, um*.03, um*.02);
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
